MERGE_MAP = {
    "人工智能": "AI",
    "芯片项目": "芯片",
    "美以伊冲突": "美伊冲突",
    "半导体行业": "半导体",
    "半导体产业": "半导体",
    "国际政治经济": "国际政治",
    "国产化替代": "国产替代",
    "质量管控": "质量管理",
    "十五五规划建议": "十五五规划",
    "巴以伊冲突": "巴以冲突",
    "以伊冲突": "美伊冲突",
}

def api_get(path, retries=5):
