        try:
            url = f"{BASE_URL}{path}"
            req = urllib.request.Request(url, headers={
                "Authorization": AUTH,
                "X-Client-ID": CLIENT_ID
            })
            with urllib.request.urlopen(req, timeout=30) as resp:
                return json.loads(resp.read())
        except urllib.error.HTTPError as e:
            if e.code == 429 and i < retries - 1:
                print(f"  Rate limited, waiting 65s (attempt {i+1}/{retries})...", flush=True)
                time.sleep(65)
            else:
                raise

def api_post(path, body, retries=5):
    for i in range(retries):
        try:
            url = f"{BASE_URL}{path}"
            data = json.dumps(body).encode()
            req = urllib.request.Request(url, data=data, headers={
                "Authorization": AUTH,
                "X-Client-ID": CLIENT_ID,
                "Content-Type": "application/json"
            })
            with urllib.request.urlopen(req, timeout=30) as resp:
                return json.loads(resp.read())
        except urllib.error.HTTPError as e:
            if e.code == 429 and i < retries - 1:
                print(f"  Rate limited, waiting 65s (attempt {i+1}/{retries})...", flush=True)
                time.sleep(65)
            else:
                raise

# Use recall API to find notes for each tag
# This is a two-pass approach:
# 1. Recall search for tag name (content-based) to get candidate note IDs
# 2. For each candidate, check if it actually has the source tag

all_candidates = {}  # note_id -> set of source tags found in it

for source_tag in MERGE_MAP.keys():
    print(f"\nSearching for notes related to: {source_tag}", flush=True)
    try:
        result = api_post("/recall", {"query": source_tag, "top_k": 30})
        results = result.get('data', {}).get('results', [])
        print(f"  Recall found {len(results)} candidates", flush=True)

        for r in results:
            note_id = r.get('note_id', '')
            if not note_id:
                continue
            if note_id not in all_candidates:
                all_candidates[note_id] = set()
            all_candidates[note_id].add(source_tag)
    except Exception as e:
        print(f"  Error: {e}", flush=True)

    time.sleep(1)

print(f"\n=== RECALL COMPLETE ===")
print(f"Total unique note candidates: {len(all_candidates)}")

# Now for each candidate, verify it has the source tag
# and collect the full info
verified_notes = {}  # note_id -> {tags, note_type, title}

for note_id, source_tags in all_candidates.items():
    try:
        result = api_get(f"/note/detail?id={note_id}")
        note = result.get('data', {}).get('note', {})
        if not note:
            continue
        note_tags = [t.get('name', '') for t in note.get('tags', [])]
        note_type = note.get('note_type', '')
        title = note.get('title', '')

        # Check which source tags are actually present
        actual_source_tags = [t for t in source_tags if t in note_tags]

        if actual_source_tags:
            verified_notes[note_id] = {
                'title': title[:60],
                'note_type': note_type,
                'tags': note_tags,
                'source_tags': actual_source_tags
            }
    except Exception as e:
        print(f"  Error getting detail for {note_id}: {e}", flush=True)

    time.sleep(0.5)

print(f"Verified notes with source tags: {len(verified_notes)}")

# Organize by source tag
by_source_tag = {}
for note_id, info in verified_notes.items():
    for st in info['source_tags']:
        if st not in by_source_tag:
            by_source_tag[st] = []
        by_source_tag[st].append({
            'note_id': note_id,
            'title': info['title'],
            'note_type': info['note_type'],
            'tags': info['tags']
        })

print("\nNotes by source tag:")
total = 0
for tag, notes in sorted(by_source_tag.items()):
    print(f"  {tag} ({len(notes)}) -> {MERGE_MAP[tag]}")
    total += len(notes)
print(f"Total: {total}")

with open('/tmp/verified_notes.json', 'w') as f:
    json.dump(verified_notes, f, ensure_ascii=False, indent=2)
with open('/tmp/by_source_tag.json', 'w') as f:
    json.dump(by_source_tag, f, ensure_ascii=False, indent=2)
print("Results saved")

